import unittest
from unittest.mock import patch
from linkmusicbot.models import Song
from linkmusicbot.services import YouTube
from linkmusicbot.services.base import same_recording


class IIIDuetTests(unittest.TestCase):
    snippet={'title':'I I I','channelTitle':'Houshou Marine - Topic','categoryId':'10',
        'description':'Provided to YouTube by cover corp.\n\nI I I · Houshou Marine · Kobo Kanaeru · Sena Kiryuin · Giga · Giga\n\nAuto-generated by YouTube.'}
    music={'videoId':'V6a1pbqlXVw','title':'I I I','length':'3:08',
           'artists':[{'name':'Houshou Marine'},{'name':'Kobo Kanaeru'}]}

    def test_authoritative_music_credits_fix_topic_composer_list(self):
        source=Song('I I I','宝鐘マリン & Kobo Kanaeru','');source.duration_ms=185876
        search={'items':[{'id':{'videoId':'V6a1pbqlXVw'},'snippet':self.snippet}]}
        with patch.object(YouTube,'_get',return_value=search),patch.object(YouTube,'_metadata_snippets',return_value={'V6a1pbqlXVw':self.snippet}),patch('linkmusicbot.services.youtube.video_music_metadata',return_value=self.music):
            self.assertTrue(YouTube().song_to_link(source).endswith('V6a1pbqlXVw'))
        response={'items':[{'snippet':self.snippet,'contentDetails':{'duration':'PT3M8S'}}]}
        with patch.object(YouTube,'_get',return_value=response),patch('linkmusicbot.services.youtube.video_music_metadata',return_value=self.music):
            actual=YouTube().link_to_song('https://music.youtube.com/watch?v=V6a1pbqlXVw')
        self.assertEqual(actual.artist,'Houshou Marine & Kobo Kanaeru')
        self.assertTrue(same_recording(source,actual.title,actual.artist,duration_ms=actual.duration_ms))

    def test_instrumental_and_unrelated_three_are_not_the_same_song(self):
        source=Song('I I I','宝鐘マリン & Kobo Kanaeru','')
        self.assertFalse(same_recording(source,'I I I (Instrumental)',source.artist))
        self.assertFalse(same_recording(source,'III','Sleep Theory'))
        self.assertFalse(same_recording(source,'I I I','Kobo Kanaeru'))

    def test_music_fallback_does_not_replace_performers_with_composers(self):
        from linkmusicbot.security import QuotaExceeded
        source=Song('I I I','宝鐘マリン & Kobo Kanaeru','');source.duration_ms=185876
        candidate=Song('I I I','Houshou Marine & Kobo Kanaeru','')
        candidate.service_links={'YouTube':'https://www.youtube.com/watch?v=V6a1pbqlXVw'}
        with patch.object(YouTube,'_get',side_effect=QuotaExceeded()),patch.object(YouTube,'_metadata_snippets',return_value={'V6a1pbqlXVw':self.snippet}),patch('linkmusicbot.services.youtube.search_music',return_value=[candidate]),patch('linkmusicbot.services.youtube.video_music_metadata',return_value=self.music):
            self.assertTrue(YouTube().song_to_link(source).endswith('V6a1pbqlXVw'))
